use clap::{CommandFactory, Parser, Subcommand};
use serde::Serialize;
use standout::cli::{App, CommandContext, Dispatch, Output};
use standout::{embed_styles, embed_templates, handler};

#[derive(Parser)]
#[command(name = "smoketable")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = handlers)]
enum Commands {
    /// Render the star catalog.
    #[dispatch(pure)]
    List,
    /// Describe this tool.
    #[dispatch(pure)]
    About,
}

#[derive(Serialize)]
struct Star {
    name: &'static str,
    constellation: &'static str,
    magnitude: f64,
}

#[derive(Serialize)]
struct Catalog {
    stars: Vec<Star>,
}

impl Catalog {
    fn fixed() -> Self {
        Catalog {
            stars: vec![
                Star { name: "Aldebaran", constellation: "Taurus", magnitude: 0.86 },
                Star { name: "Rigel", constellation: "Orion", magnitude: 0.13 },
                Star { name: "Vega", constellation: "Lyra", magnitude: 0.03 },
            ],
        }
    }
}

#[derive(Serialize)]
struct AboutInfo {
    name: &'static str,
    description: &'static str,
}

mod handlers {
    use super::*;

    #[handler]
    pub fn list(#[ctx] _ctx: &CommandContext) -> Result<Output<Catalog>, anyhow::Error> {
        Ok(Output::Render(Catalog::fixed()))
    }

    #[handler]
    pub fn about(#[ctx] _ctx: &CommandContext) -> Result<Output<AboutInfo>, anyhow::Error> {
        Ok(Output::Render(AboutInfo {
            name: "smoketable",
            description: "a tiny CLI that renders a fixed catalog of bright stars",
        }))
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let app = App::builder()
        .templates(embed_templates!("src/templates"))
        .styles(embed_styles!("src/styles"))
        .default_theme("default")
        .commands(Commands::dispatch_config())?
        .build()?;

    app.run(Cli::command(), std::env::args());
    Ok(())
}

